-- Cash Management: append-only physical tender authority (ADR-0039/0040).
CREATE TABLE cash_registers(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','MAINTENANCE','ARCHIVED')),default_currency char(3) NOT NULL,default_opening_float_minor bigint,drawer_id uuid,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,branch_id,code));
CREATE TABLE cash_drawers(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','ASSIGNED','IN_USE','OUT_OF_SERVICE','ARCHIVED')),register_id uuid,hardware_reference text,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,branch_id,code));
CREATE TABLE cash_policies(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid,register_id uuid,id uuid NOT NULL DEFAULT gen_random_uuid(),configuration jsonb NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_sessions(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),register_id uuid NOT NULL,drawer_id uuid,opened_by_user_id uuid NOT NULL,opened_by_membership_id uuid NOT NULL,assigned_cashier_id uuid NOT NULL,currency char(3) NOT NULL,business_date date NOT NULL,status text NOT NULL CHECK(status IN('PENDING_OPEN','OPEN','SUSPENDED','COUNTING','RECONCILIATION_REQUIRED','PENDING_APPROVAL','CLOSED','FORCE_CLOSED','REOPENED','CANCELLED')),opening_float_minor bigint NOT NULL CHECK(opening_float_minor>=0),expected_amount_minor bigint NOT NULL DEFAULT 0,counted_amount_minor bigint,variance_minor bigint,opened_at timestamptz,closed_at timestamptz,suspended_at timestamptz,reopened_at timestamptz,version integer NOT NULL DEFAULT 1,correlation_id uuid NOT NULL,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,register_id) REFERENCES cash_registers(tenant_id,id),FOREIGN KEY(tenant_id,drawer_id) REFERENCES cash_drawers(tenant_id,id));
CREATE UNIQUE INDEX cash_one_active_register ON cash_sessions(tenant_id,register_id) WHERE status IN('PENDING_OPEN','OPEN','SUSPENDED','COUNTING','RECONCILIATION_REQUIRED','PENDING_APPROVAL','REOPENED');
CREATE UNIQUE INDEX cash_one_active_drawer ON cash_sessions(tenant_id,drawer_id) WHERE drawer_id IS NOT NULL AND status IN('PENDING_OPEN','OPEN','SUSPENDED','COUNTING','RECONCILIATION_REQUIRED','PENDING_APPROVAL','REOPENED');
CREATE UNIQUE INDEX cash_one_active_cashier_branch ON cash_sessions(tenant_id,branch_id,assigned_cashier_id) WHERE status IN('PENDING_OPEN','OPEN','SUSPENDED','COUNTING','RECONCILIATION_REQUIRED','PENDING_APPROVAL','REOPENED');
CREATE TABLE cash_ledger_entries(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,register_id uuid NOT NULL,drawer_id uuid,currency char(3) NOT NULL,direction text NOT NULL CHECK(direction IN('IN','OUT')),movement_type text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),source_type text NOT NULL,source_id text NOT NULL,sale_id uuid,payment_allocation_id uuid,reference text,reason text NOT NULL,actor_id uuid NOT NULL,membership_id uuid NOT NULL,approved_by uuid,occurred_at timestamptz NOT NULL,business_date date NOT NULL,idempotency_key text NOT NULL,correlation_id uuid NOT NULL,causation_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,session_id) REFERENCES cash_sessions(tenant_id,id),UNIQUE(tenant_id,source_type,source_id),UNIQUE(tenant_id,session_id,idempotency_key));
CREATE INDEX cash_ledger_session_timeline ON cash_ledger_entries(tenant_id,session_id,occurred_at,id);
CREATE TABLE cash_counts(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,currency char(3) NOT NULL,kind text NOT NULL CHECK(kind IN('TOTAL','DENOMINATION')),counted_amount_minor bigint NOT NULL CHECK(counted_amount_minor>=0),sequence integer NOT NULL,actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),notes text,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,session_id,sequence));
CREATE TABLE cash_count_denominations(tenant_id uuid NOT NULL,count_id uuid NOT NULL,denomination_minor bigint NOT NULL CHECK(denomination_minor>0),quantity integer NOT NULL CHECK(quantity>=0),PRIMARY KEY(tenant_id,count_id,denomination_minor),FOREIGN KEY(tenant_id,count_id) REFERENCES cash_counts(tenant_id,id));
CREATE TABLE cash_reconciliations(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,expected_amount_minor bigint NOT NULL,counted_amount_minor bigint NOT NULL,variance_minor bigint NOT NULL,status text NOT NULL,severity text NOT NULL,reason text,actor_id uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_variances(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,reconciliation_id uuid NOT NULL,amount_minor bigint NOT NULL,status text NOT NULL,reason text,actor_id uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_approvals(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),action_type text NOT NULL,resource_id uuid NOT NULL,requested_by uuid NOT NULL,requested_at timestamptz NOT NULL,required_permission text NOT NULL,threshold_minor bigint,reason text NOT NULL,status text NOT NULL CHECK(status IN('PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED')),decided_by uuid,decided_at timestamptz,decision_reason text,expires_at timestamptz NOT NULL,correlation_id uuid NOT NULL,version integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_deposits(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,destination text NOT NULL,reference text,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency char(3) NOT NULL,status text NOT NULL CHECK(status IN('PREPARED','HANDED_OVER','CONFIRMED_MANUALLY','CANCELLED')),actor_id uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_transfers(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),source_session_id uuid NOT NULL,destination_session_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency char(3) NOT NULL,status text NOT NULL,reference text NOT NULL,idempotency_key text NOT NULL,actor_id uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE cash_receipts(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),session_id uuid NOT NULL,kind text NOT NULL,model jsonb NOT NULL,content_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_idempotency_records(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,operation text NOT NULL,key text NOT NULL,request_fingerprint char(64) NOT NULL,response jsonb NOT NULL,status_code integer NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,operation,key));
CREATE TABLE cash_events(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,event_type text NOT NULL,event_version integer NOT NULL,aggregate_id uuid NOT NULL,aggregate_version integer NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,correlation_id uuid NOT NULL,actor_id uuid NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE cash_outbox(tenant_id uuid NOT NULL,organization_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,event_type text NOT NULL,event_version integer NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,attempts integer NOT NULL DEFAULT 0,last_error text,PRIMARY KEY(tenant_id,id));
CREATE INDEX cash_outbox_pending ON cash_outbox(published_at,occurred_at);

DO $cash$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['cash_registers','cash_drawers','cash_policies','cash_sessions','cash_ledger_entries','cash_counts','cash_count_denominations','cash_reconciliations','cash_variances','cash_approvals','cash_deposits','cash_transfers','cash_receipts','cash_idempotency_records','cash_events','cash_outbox'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n); EXECUTE format('CREATE POLICY tenant_isolation ON %I AS RESTRICTIVE FOR ALL TO nexo_migration,nexo_runtime,nexo_readonly USING (tenant_id=app.current_tenant_id()) WITH CHECK (tenant_id=app.current_tenant_id())',n); EXECUTE format('CREATE POLICY runtime_access ON %I FOR ALL TO nexo_runtime USING (tenant_id=app.current_tenant_id()) WITH CHECK (tenant_id=app.current_tenant_id())',n); EXECUTE format('CREATE POLICY readonly_access ON %I FOR SELECT TO nexo_readonly USING (tenant_id=app.current_tenant_id())',n); END LOOP; END $cash$;
GRANT SELECT,INSERT,UPDATE ON cash_registers,cash_drawers,cash_policies,cash_sessions,cash_counts,cash_count_denominations,cash_reconciliations,cash_variances,cash_approvals,cash_deposits,cash_transfers,cash_idempotency_records TO nexo_runtime;
GRANT SELECT,INSERT ON cash_ledger_entries,cash_receipts,cash_events,cash_outbox TO nexo_runtime;
GRANT SELECT ON cash_registers,cash_drawers,cash_policies,cash_sessions,cash_ledger_entries,cash_counts,cash_count_denominations,cash_reconciliations,cash_variances,cash_approvals,cash_deposits,cash_transfers,cash_receipts,cash_events TO nexo_readonly;
GRANT SELECT,UPDATE ON cash_outbox TO nexo_worker;
CREATE POLICY cash_outbox_worker_select ON cash_outbox FOR SELECT TO nexo_worker USING(true);
CREATE POLICY cash_outbox_worker_update ON cash_outbox FOR UPDATE TO nexo_worker USING(true) WITH CHECK(true);
CREATE FUNCTION app.prevent_cash_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'CASH_LEDGER_IMMUTABLE'; END $$;
CREATE TRIGGER cash_ledger_immutable BEFORE UPDATE OR DELETE ON cash_ledger_entries FOR EACH ROW EXECUTE FUNCTION app.prevent_cash_history_mutation();
CREATE TRIGGER cash_events_immutable BEFORE UPDATE OR DELETE ON cash_events FOR EACH ROW EXECUTE FUNCTION app.prevent_cash_history_mutation();
CREATE TRIGGER cash_receipts_immutable BEFORE UPDATE OR DELETE ON cash_receipts FOR EACH ROW EXECUTE FUNCTION app.prevent_cash_history_mutation();
